package com.acme.preview.mapper;

import com.acme.preview.event.PriceEvent;

import java.util.function.Function;

/**
 * Maps a CSV line ("symbol,price,volume") to a {@link PriceEvent}. Wired as the file feed's
 * valueMapper, so the hosted graph receives typed PriceEvents rather than raw Strings.
 * Implements {@code Function<Object,?>} (the feed-wrapper's value type) and tolerates blank or
 * short lines (e.g. a trailing newline) so the feed never throws.
 */
public class CsvToPriceEvent implements Function<Object, PriceEvent> {

    @Override
    public PriceEvent apply(Object event) {
        String line = String.valueOf(event);
        String[] f = line.split(",");
        if (f.length < 3) {
            return new PriceEvent(line.trim(), 0.0, 0L);
        }
        return new PriceEvent(f[0].trim(), Double.parseDouble(f[1].trim()), Long.parseLong(f[2].trim()));
    }
}
package com.acme.preview;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.Optional;

/**
 * The bundle's own lifecycle commands — {@code export} and {@code stop} — implemented with nothing
 * but the JDK (plus Jackson, already on this project's classpath via the admin console) so the
 * bundle keeps its "nothing but a JDK" promise on every platform, Windows included.
 *
 * <p><b>Registry resolution.</b> The admin console publishes {@code <registry>/preview-smoke}
 * while the server is up. Both the server and this helper resolve {@code <registry>} as the
 * {@code mongoose.servers.dir} system property when set, else {@code <user.home>/.mongoose/servers}
 * — the JVM's user.home, not the shell's $HOME, because those can differ under launchers,
 * containers and test harnesses.
 *
 * <p>Registry content is DATA: it is parsed as JSON and its values are only ever used as a URL, a
 * header value and a pid. Nothing here is passed to a shell.
 */
public final class BundleLifecycle {

    private static final String SERVER_NAME = "preview-smoke";
    /** This project's jar, by exact file name — part of the stop identity check. */
    private static final String JAR_NAME = "preview-smoke-1.0.0-SNAPSHOT.jar";
    private static final String EXPORT_PATH = "logs/audit-preview-smoke.yaml";

    public static void main(String[] args) {
        String command = args.length > 0 ? args[0] : "";
        try {
            switch (command) {
                case "export" -> export();
                case "stop" -> stop();
                default -> {
                    System.err.println("usage: BundleLifecycle <export|stop>");
                    System.exit(2);
                }
            }
        } catch (Exception e) {
            System.err.println(command + " failed: " + e);
            System.exit(1);
        }
    }

    /** {@code <registry>/<serverName>}, resolved exactly as the server resolves it. */
    static Path registryEntry() {
        String configured = System.getProperty("mongoose.servers.dir");
        Path dir = (configured != null && !configured.isBlank())
                ? Paths.get(configured)
                : Paths.get(System.getProperty("user.home"), ".mongoose", "servers");
        return dir.resolve(SERVER_NAME);
    }

    private static JsonNode readRegistry() throws Exception {
        Path entry = registryEntry();
        if (!Files.isRegularFile(entry)) {
            throw new IllegalStateException("no registry entry at " + entry
                    + " — is the server running? start it with ./run-server.sh");
        }
        return new ObjectMapper().readTree(Files.readString(entry));
    }

    /** The export beat: Mongoose captures to Chronicle, so analyser-readable YAML is produced by
     *  the admin API, never by the run itself. */
    private static void export() throws Exception {
        JsonNode registry = readRegistry();
        String base = registry.path("url").asText();
        String authMode = registry.path("authMode").asText("NONE");
        String token = registry.path("token").asText("");
        HttpClient http = HttpClient.newHttpClient();

        // the listing is a bare JSON array of {id, ...}; a {"files":[...]} wrapper is tolerated
        JsonNode listing = new ObjectMapper().readTree(get(http, base + "/api/audit/files", authMode, token));
        JsonNode files = listing.isArray() ? listing : listing.path("files");
        if (!files.isArray() || files.isEmpty()) {
            throw new IllegalStateException("no captured audit files yet — auditCapture records after "
                    + "events flow; check autoStart in config/server-config.yml");
        }
        String id = files.get(0).path("id").asText();

        String yaml = get(http, base + "/api/audit/file/" + id + "/export?format=yaml", authMode, token);
        Path out = Paths.get(EXPORT_PATH);
        if (out.getParent() != null) Files.createDirectories(out.getParent());
        Files.writeString(out, yaml);
        System.out.println("exported " + EXPORT_PATH + " (audit file id: " + id + ")");
        System.out.println("open it with the Fluxtion Audit Log Analyser — see README.md");
    }

    private static String get(HttpClient http, String url, String authMode, String token) throws Exception {
        HttpRequest.Builder request = HttpRequest.newBuilder(URI.create(url)).GET();
        if ("BEARER".equals(authMode) && !token.isEmpty()) {
            request.header("Authorization", "Bearer " + token);
        }
        HttpResponse<String> response = http.send(request.build(), HttpResponse.BodyHandlers.ofString());
        if (response.statusCode() / 100 != 2) {
            throw new IllegalStateException("HTTP " + response.statusCode() + " for " + url);
        }
        return response.body();
    }

    /**
     * Stop the server named by the registry entry — but only after establishing that the live
     * process really IS this project's server.
     *
     * <p>A crash leaves the entry behind and the OS may reuse the pid, so "is it alive" is not
     * identity. Substring-matching the artifact name is not identity either: any process whose
     * arguments happen to contain the name matches, and a review demonstrated exactly that by
     * pointing this command at a non-Java test stub invoked with {@code --name <artifact>}. All
     * THREE of these must hold, and a failure of any one refuses rather than signalling a stranger:
     *
     * <ol>
     *   <li>the executable is {@code java};</li>
     *   <li>the command line runs THIS project's jar, by its exact file name;</li>
     *   <li>the process did not start AFTER the registry entry it supposedly wrote — a recycled pid
     *       almost always fails this.</li>
     * </ol>
     */
    private static void stop() throws Exception {
        Path entry = registryEntry();
        if (!Files.isRegularFile(entry)) {
            System.out.println("no registry entry at " + entry + " — nothing to stop.");
            return;
        }
        JsonNode registry = new ObjectMapper().readTree(Files.readString(entry));
        long pid = registry.path("pid").asLong();
        Optional<ProcessHandle> found = ProcessHandle.of(pid);
        if (found.isEmpty() || !found.get().isAlive()) {
            System.out.println("pid " + pid + " is not running — stale entry from a crash; leaving it "
                    + "for inspection");
            return;
        }
        ProcessHandle handle = found.get();
        ProcessHandle.Info info = handle.info();
        String executable = info.command().orElse("");
        String commandLine = info.commandLine().orElse("");

        String reason = null;
        if (!isJavaExecutable(executable)) {
            reason = "its executable is not java (" + (executable.isEmpty() ? "unknown" : executable) + ")";
        } else if (!commandLine.contains(JAR_NAME)) {
            reason = "its command line does not run " + JAR_NAME;
        } else if (startedAfter(info, registry.path("startedAt").asText(""))) {
            reason = "it started AFTER the registry entry it would have written — the pid was reused";
        }
        if (reason != null) {
            System.err.println("REFUSING to signal pid " + pid + ": " + reason + ".");
            System.err.println("  registry entry: " + entry + " (likely stale, pid reused after a crash)");
            System.err.println("  running command: " + (commandLine.isEmpty() ? executable : commandLine));
            System.exit(1);
        }

        handle.destroy();   // SIGTERM on POSIX; the server's shutdown hook closes capture
        // Do not CLAIM a clean stop — observe one. The registry entry is removed by the server's own
        // shutdown path, so its disappearance is the evidence that the stop was clean.
        handle.onExit().get(30, java.util.concurrent.TimeUnit.SECONDS);
        for (int i = 0; i < 100 && Files.exists(entry); i++) {
            Thread.sleep(100);
        }
        if (Files.exists(entry)) {
            System.err.println("stopped server pid " + pid + ", but its registry entry is STILL at "
                    + entry + " — the shutdown path did not remove it, so do not treat this as a "
                    + "clean stop");
            System.exit(1);
        }
        System.out.println("stopped server pid " + pid + " — Chronicle capture closed and the "
                + "registry entry was removed");
    }

