package com.acme.preview.builder;

import com.telamin.fluxtion.runtime.DataFlow;
import java.util.function.Supplier;

/**
 * Builds the hosted Fluxtion graph for Mongoose. Referenced from server-config.yml
 * (eventHandlerBuilder:) and MongooseProgrammaticMain (.handlerBuilder(...)).
 * AOT: MarketProcessor is generated at build time by the fluxtion-maven-plugin
 * (from SpringAotBuilder, which applies application-context.xml) and loaded reflectively — no compiler or API key at runtime.
 */
public class MarketProcessorSupplier implements Supplier<DataFlow> {

    @Override
    public DataFlow get() {
        DataFlow flow;
        try {
            flow = (DataFlow) Class.forName("com.acme.preview.generated.MarketProcessor")
                    .getDeclaredConstructor().newInstance();
        } catch (ReflectiveOperationException e) {
            throw new IllegalStateException("generated processor not found — run './mvnw package'", e);
        }
        // Surface any event that reaches no @OnEventHandler — e.g. a file feed delivering raw String
        // with no valueMapper. Without this it is silently dropped.
        flow.setUnKnownEventHandler(e -> System.out.println(
                "unhandled event (no @OnEventHandler matched — add a handler or a feed valueMapper): " + e));
        // Print audit records to stdout — the default java.util.logging sink is invisible in the
        // Playground console, so an audited graph would otherwise look idle.
        flow.setAuditLogProcessor(logRecord -> System.out.println(logRecord));
        return flow;
    }
}
