#!/bin/bash
# Boot the Mongoose server. Builds the fat jar on first run. Web console: http://127.0.0.1:8181.
# --add-opens flags are required: Agrona/Aeron (via Mongoose) access jdk.internal.misc.Unsafe.
# (The jar manifest also carries Add-Opens; explicit flags keep the script correct if the
# jar is rebuilt without the manifest entry or run through a wrapper.)
# The config file rides in as -DmongooseServer.config.file so services that re-read the
# descriptor (e.g. the web admin console) resolve the same yaml.
set -e
cd "$(dirname "${BASH_SOURCE[0]}")"
JAR="target/preview-smoke-1.0.0-SNAPSHOT.jar"
[ -f "$JAR" ] || ./mvnw -q package
# The registry directory override must reach the SERVER too, not just export/stop: the admin console
# publishes ~/.mongoose/servers/<name> from inside this JVM, so if only the helper commands honoured
# MONGOOSE_SERVERS_DIR the three commands would resolve different directories (analyser review F2).
OPTS=()
[ -n "${MONGOOSE_SERVERS_DIR:-}" ] && OPTS+=("-Dmongoose.servers.dir=${MONGOOSE_SERVERS_DIR}")
exec java "${OPTS[@]}" \
  -DmongooseServer.config.file=config/server-config.yml \
  --add-opens java.base/jdk.internal.misc=ALL-UNNAMED \
  --add-opens java.base/java.lang.reflect=ALL-UNNAMED \
  --add-opens java.base/java.io=ALL-UNNAMED \
  --add-opens java.base/java.nio=ALL-UNNAMED \
  --add-opens java.base/sun.nio.ch=ALL-UNNAMED \
  --add-opens java.base/jdk.internal.ref=ALL-UNNAMED \
  --add-opens java.base/jdk.internal.util=ALL-UNNAMED \
  -jar "$JAR"
#!/bin/bash
# Export the captured audit as analyser-readable YAML — logs/audit-preview-smoke.yaml.
# Everything below is the JDK: the work is done by com.acme.preview.BundleLifecycle, so this
# needs no host tooling beyond the JDK, and export-audit.cmd is the same command on Windows.
set -e
cd "${BASH_SOURCE[0]%/*}" 2>/dev/null || true   # bash builtin — avoids tools a JDK does not supply
JAR="target/preview-smoke-1.0.0-SNAPSHOT.jar"
[ -f "$JAR" ] || ./mvnw -q package
# Pass the isolation override through as the system property the SERVER also reads, so the two can
# never resolve different registry directories.
OPTS=()
[ -n "${MONGOOSE_SERVERS_DIR:-}" ] && OPTS+=("-Dmongoose.servers.dir=${MONGOOSE_SERVERS_DIR}")
exec java "${OPTS[@]}" -cp "$JAR" com.acme.preview.BundleLifecycle export
#!/bin/bash
# Stop this project's Mongoose server, found via its registry entry.
# Everything below is the JDK: the work is done by com.acme.preview.BundleLifecycle, so this
# needs no host tooling beyond the JDK, and stop-server.cmd is the same command on Windows.
